set -euo pipefail

PLUGIN_ROOT="${CLAUDE_PLUGIN_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
SKILL_FILE="${PLUGIN_ROOT}/../../skills/dysflow-protocol/SKILL.md"

# 1. Surface the canonical 8-step loop so the agent always sees it.
